<script setup>import {ref,computed} from 'vue';import {useStudy} from '../stores/study';import PageHeading from '../components/PageHeading.vue';import StatCard from '../components/StatCard.vue';import ProgressBar from '../components/ProgressBar.vue';import TaskItem from '../components/TaskItem.vue';import TaskForm from '../components/TaskForm.vue';import EmptyState from '../components/EmptyState.vue';import ToastMessage from '../components/ToastMessage.vue';import QuoteCard from '../components/QuoteCard.vue';const s=useStudy(),show=ref(false),toast=ref('');const date=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());function notify(m){toast.value=m;setTimeout(()=>toast.value='',2000)}async function add(d){await s.add(d);show.value=false;notify('新任务添加成功！')}async function toggle(id){const t=s.tasks.value.find(t=>t.id===id);await s.toggle(id);notify(t?.done?'已移回待办':'太棒了！完成一项任务')}async function remove(id){await s.remove(id);notify('任务已删除')}</script><template><section><PageHeading eyebrow="YOUR DAILY SPACE" title="今天也要进步一点点！" :subtitle="date+' · 把大目标拆成小行动。'"/><div class="stats-grid"><StatCard label="今日完成" :value="`${s.done.value.length} / ${s.tasks.value.length}`" note="每一步都值得鼓励" icon="✓"/><StatCard label="学习时长" :value="`${s.minutes.value} 分钟`" note="已完成任务的预计时长" icon="◷"/><StatCard label="连续打卡" value="7 天" note="坚持会带来改变" icon="♨"/></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><small class="eyebrow">YOUR CHECKLIST</small><h2>今日学习计划 <span class="pill">{{s.tasks.value.length}}</span></h2></div><button class="secondary" @click="show=!show">{{show?'收起':'＋ 添加任务'}}</button></div><ProgressBar :value="s.rate.value" label="今日完成进度"/><Transition name="expand"><div v-if="show" class="form-wrap"><TaskForm @submit="add"/></div></Transition><div v-if="s.tasks.value.length" class="task-list"><TaskItem v-for="task in s.tasks.value" :key="task.id" :task="task" @toggle="toggle" @delete="remove"/></div><EmptyState v-else/><div v-if="s.tasks.value.length&&s.pending.value.length===0" class="all-done">✨ 全部完成！你今天超棒的！</div></section><aside class="right-column"><div class="panel mini"><span class="mini-icon">☷</span><h3>待办任务</h3><strong>{{s.pending.value.length}} <small>项</small></strong><p>还有 {{s.pending.value.reduce((n,t)=>n+Number(t.minutes),0)}} 分钟的计划</p></div><QuoteCard/><div class="tip"><b>💡 今日小建议</b><p>试试番茄工作法：专注学习 25 分钟，再休息 5 分钟。</p></div></aside></div><ToastMessage :message="toast"/></section></template>